    int length = 0;
    uint8_t c = 0;
    uint32_t start = HAL_GetTick();
    while (HAL_GetTick() - start < timeoutMs) {
        if (HAL_UART_Receive(&huart1, &c, 1, 1) != HAL_OK) continue;
        if (c == '\n') {
            line[length] = 0;
            return length;
        }
        if (c != '\r' && length < size - 1) line[length++] = c;
    }
    line[length] = 0;
    return -1;
}
